-- 025: Per-org agreement template for A5 e-sign.
--
-- Documenso signs a FILE. The e-sign flow previously sent only a title, so
-- Documenso created an empty draft and every "signing link" 404'd — a draft
-- has no signing page. Fixing the API call is necessary but not sufficient:
-- there has to be a document to sign.
--
-- The template is uploaded by the customer, never generated by us. Drafting
-- indemnification / hold-harmless language would be practising law
-- (docs/08 §3 + the "not legal, insurance, or professional advice" rule), so
-- the product's job is to store the customer's own lawyer-reviewed PDF and
-- route it for signature.
--
-- Storage: reuses the existing private `cois` bucket at
-- {org_id}/agreements/{filename}. The bucket policies from migration 002 are
-- already scoped by org folder, so no storage policy changes are needed and
-- no path outside the org's own folder becomes reachable.

alter table public.orgs
  add column if not exists agreement_template_path text,
  add column if not exists agreement_template_name text,
  add column if not exists agreement_template_uploaded_at timestamptz;

comment on column public.orgs.agreement_template_path is
  'Storage object path in the private `cois` bucket ({org_id}/agreements/...). '
  'Null means e-sign is unavailable for this org and the UI says so instead of '
  'minting a link that cannot work.';
